  1	/* ============================================================
  2	   views/config-persona-models.js — Persona Models tab module
  3	   Section 4d-pm of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, configDirty (defined in config.js)
  5	   Must be loaded BEFORE config.js.
  6	   ============================================================ */
  7	
  8	/* ── Module-level state ──────────────────────────────────── */
  9	
 10	/* Module-level state for Persona Models tab.
 11	   pmModels:       working copy of model list (loaded from server, used for dropdowns).
 12	   pmPersonas:     full persona list from GET /api/personas.
 13	   pmAssignments:  working copy of assignments (default_model_uuid + persona_models).
 14	   pmOriginal:     snapshot of assignments at load/save time for dirty comparison.
 15	   pmIsBuilding:   true while a rebuild is in progress.
 16	   pmCollapsed:    set of suite names the user has collapsed.
 17	   pmReplaceOpen:  true when the Replace Model inline form is shown. */
 18	var pmModels      = null;   /* ModelEntry[] | null */
 19	var pmPersonas    = null;   /* PersonaEntry[] | null */
 20	var pmAssignments = null;   /* { default_model_uuid?: string, persona_models: {} } | null */
 21	var pmOriginal    = null;   /* deep-cloned snapshot for dirty comparison */
 22	var pmIsBuilding  = false;
 23	var pmCollapsed   = {};     /* { [suiteName]: boolean } */
 24	var pmReplaceOpen = false;
 25	
 26	/* Suite display labels — maps raw suite keys to user-facing strings. */
 27	var PM_SUITE_LABELS = {
 28	  'ledger':         'Ledger',
 29	  'standalone':     'Standalone',
 30	  'ledger-support': 'Ledger Support'
 31	};
 32	
 33	/* Ordered suite list for consistent rendering. */
 34	var PM_SUITE_ORDER = ['ledger', 'standalone', 'ledger-support'];
 35	
 36	/* ── Helpers ─────────────────────────────────────────────── */
 37	
 38	/** Deep-clone assignments object. */
 39	function pmCloneAssignments(a) {
 40	  if (!a) return { persona_models: {} };
 41	  return {
 42	    default_model_uuid: a.default_model_uuid,
 43	    persona_models: Object.assign({}, a.persona_models || {})
 44	  };
 45	}
 46	
 47	/** Return true when working copy has unsaved changes vs snapshot. */
 48	function pmHasChanges() {
 49	  if (!pmAssignments || !pmOriginal) return false;
 50	  if (pmAssignments.default_model_uuid !== pmOriginal.default_model_uuid) return true;
 51	  var aPm = pmAssignments.persona_models || {};
 52	  var oPm = pmOriginal.persona_models || {};
 53	  var aKeys = Object.keys(aPm);
 54	  var oKeys = Object.keys(oPm);
 55	  if (aKeys.length !== oKeys.length) return true;
 56	  for (var i = 0; i < aKeys.length; i++) {
 57	    if (aPm[aKeys[i]] !== oPm[aKeys[i]]) return true;
 58	  }
 59	  return false;
 60	}
 61	
 62	/** Resolve a model UUID to its display name. Returns null when not found. */
 63	function pmModelName(uuid) {
 64	  if (!uuid || !pmModels) return null;
 65	  for (var i = 0; i < pmModels.length; i++) {
 66	    if (pmModels[i].id === uuid) return pmModels[i].name;
 67	  }
 68	  return null;
 69	}
 70	
 71	/** Render a dirty indicator dot. */
 72	function pmDirtyDot(isDirty) {
 73	  return isDirty ? '<span class="pm-dirty-dot" title="Unsaved change"></span>' : '';
 74	}
 75	
 76	/** Build <option> elements for a model dropdown.
 77	 *  If includeDefault is true, prepends a "Default" option with value ''. */
 78	function pmBuildModelOptions(selectedUuid, includeDefault) {
 79	  var opts = '';
 80	  if (includeDefault) {
 81	    opts += '<option value=""' + (!selectedUuid ? ' selected' : '') + '>Default</option>';
 82	  }
 83	  if (pmModels) {
 84	    for (var i = 0; i < pmModels.length; i++) {
 85	      var m = pmModels[i];
 86	      var sel = (m.id === selectedUuid) ? ' selected' : '';
 87	      opts += '<option value="' + escapeHtml(m.id) + '"' + sel + '>' + escapeHtml(m.name) + '</option>';
 88	    }
 89	  }
 90	  return opts;
 91	}
 92	
 93	/* ── Full tab rebuild ────────────────────────────────────── */
 94	
 95	/** (Re-)render the Persona Models tab content and re-wire events. */
 96	function pmRefreshTab() {
 97	  var contentEl = document.getElementById('config-tab-content');
 98	  if (!contentEl) return;
 99	  contentEl.innerHTML = pmBuildTabHtml();
100	  pmWireEvents();

101	  /* Sync dirty flag */
102	  configDirty.personaModels = pmHasChanges();
103	}
104	
105	/** Build the full HTML string for the Persona Models tab. */
106	function pmBuildTabHtml() {
107	  /* ── Empty-registry edge case ── */
108	  if (!pmModels || pmModels.length === 0) {
109	    return UI.card('Persona Models',
110	      '<div class="pm-empty-registry">' +
111	        '<p>No models are registered. To assign models to personas, first add models in the ' +
112	        '<button class="btn-link pm-goto-registry">Model Registry</button> tab.</p>' +
113	      '</div>'
114	    );
115	  }
116	
117	  /* ── Pre-build state: no personas yet ── */
118	  if (!pmPersonas || pmPersonas.length === 0) {
119	    return UI.card('Persona Models',
120	      '<div class="pm-prebuild-state">' +
121	        '<p><strong>No persona data available.</strong> Run the persona build to generate persona output files and populate this tab.</p>' +
122	        '<button id="pm-prebuild-rebuild-btn" class="btn btn-primary"' + (pmIsBuilding ? ' disabled' : '') + '>' +
123	          (pmIsBuilding ? '<span class="spinner"></span> Rebuilding…' : 'Rebuild Personas') +
124	        '</button>' +
125	        '<div id="pm-build-error" style="display:none;"></div>' +
126	      '</div>'
127	    );
128	  }
129	
130	  /* ── Stale banner ── */
131	  var staleBanner = '';
132	  if (pmAssignments && pmAssignments.stale) {
133	    staleBanner =
134	      '<div class="stale-banner pm-stale-banner" id="pm-stale-banner">' +
135	        '<span>Model settings have changed since the last persona build.</span>' +
136	        '<button id="pm-banner-rebuild-btn" class="btn btn-sm btn-secondary"' + (pmIsBuilding ? ' disabled' : '') + '>' +
137	          (pmIsBuilding ? '<span class="spinner"></span> Rebuilding…' : 'Rebuild Personas') +
138	        '</button>' +
139	      '</div>';
140	  }
141	
142	  /* ── Build error area (always present, hidden unless error occurred) ── */
143	  var buildErrorArea =
144	    '<div id="pm-build-error" style="display:none;margin-bottom:12px;"></div>';
145	
146	  /* ── Default model section ── */
147	  var savedDefaultUuid    = pmOriginal ? pmOriginal.default_model_uuid : undefined;
148	  var currentDefaultUuid  = pmAssignments ? pmAssignments.default_model_uuid : undefined;
149	  var defaultDirty        = (currentDefaultUuid !== savedDefaultUuid);
150	  var defaultModelName    = pmModelName(currentDefaultUuid) || 'None selected';
151	
152	  var defaultSection =
153	    '<div class="pm-section" style="margin-bottom:20px;">' +
154	      '<h3 class="mr-section-title">Default Model</h3>' +
155	      '<div class="pm-default-row">' +
156	        '<div class="pm-default-display" id="pm-default-display">' +
157	          pmDirtyDot(defaultDirty) +
158	          '<span class="pm-model-text">' + escapeHtml(defaultModelName) + '</span>' +
159	          '<button class="btn-icon pm-edit-default-btn" title="Edit default model" aria-label="Edit default model">&#9998;</button>' +
160	        '</div>' +
161	        '<div class="pm-default-edit" id="pm-default-edit" style="display:none;">' +
162	          '<select id="pm-default-select" class="form-control pm-model-select">' +
163	            pmBuildModelOptions(currentDefaultUuid, false) +
164	          '</select>' +
165	          '<button id="pm-default-done-btn" class="btn btn-sm btn-primary" style="margin-left:8px;">Done</button>' +
166	          '<button id="pm-default-cancel-btn" class="btn btn-sm btn-secondary" style="margin-left:6px;">Cancel</button>' +
167	        '</div>' +
168	      '</div>' +
169	    '</div>';
170	
171	  /* ── Persona Assignments section ── */
172	  /* Group personas by suite */
173	  var suiteGroups = {};
174	  PM_SUITE_ORDER.forEach(function (s) { suiteGroups[s] = []; });
175	  (pmPersonas || []).forEach(function (p) {
176	    var suite = p.suite || 'ledger';
177	    if (!suiteGroups[suite]) suiteGroups[suite] = [];
178	    suiteGroups[suite].push(p);
179	  });
180	
181	  /* Replace Model inline form */
182	  var replaceFormHtml = '';
183	  if (pmReplaceOpen) {
184	    var replaceFromOpts = pmBuildModelOptions(null, false);
185	    var replaceToOpts   = pmBuildModelOptions(null, false);
186	    replaceFormHtml =
187	      '<div class="pm-replace-form" id="pm-replace-form">' +
188	        '<div class="pm-replace-row">' +
189	          '<div class="form-group pm-replace-field">' +
190	            '<label class="form-label" for="pm-replace-from">Replace</label>' +
191	            '<select id="pm-replace-from" class="form-control">' + replaceFromOpts + '</select>' +
192	          '</div>' +
193	          '<div class="form-group pm-replace-field">' +
194	            '<label class="form-label" for="pm-replace-to">With</label>' +
195	            '<select id="pm-replace-to" class="form-control">' + replaceToOpts + '</select>' +
196	          '</div>' +
197	          '<div class="form-group pm-replace-action">' +
198	            '<label class="form-label" style="visibility:hidden;">Action</label>' +
199	            '<button id="pm-replace-all-btn" class="btn btn-secondary">Replace All</button>' +
200	            '<button id="pm-replace-cancel-btn" class="btn btn-secondary" style="margin-left:6px;">Cancel</button>' +
201	          '</div>' +
202	        '</div>' +
203	        '<div id="pm-replace-msg"></div>' +
204	      '</div>';
205	  }
206	
207	  /* Suite sections */
208	  var suiteSectionsHtml = '';
209	  PM_SUITE_ORDER.forEach(function (suite) {
210	    var personas = suiteGroups[suite] || [];
211	    if (personas.length === 0) return;
212	
213	    var label     = PM_SUITE_LABELS[suite] || suite;
214	    var collapsed = !!pmCollapsed[suite];
215	
216	    /* Persona rows */
217	    var rowsHtml = '';
218	    personas.forEach(function (p) {
219	      var currentUuid = (pmAssignments && pmAssignments.persona_models)
220	        ? (pmAssignments.persona_models[p.id] || '')

